# name -> (colour, path). Flattened once, and a name used twice is a mistake
# rather than a silent winner -- the same rule the emoji list lives under.
LOGOS = {}
for _slug, _words, _hex, _d in LOGO_LIST:
    for _word in _words.split():
        if _word in LOGOS and LOGOS[_word] != (_hex, _d):
            raise ValueError(f"the logo name {_word!r} is used twice")
        LOGOS[_word] = (_hex, _d)
